// Build list of [post_type, target_lang] pairs to process
const languages = $input.all().map(i => i.json);
const config = $('Config Variables').first().json;

const postTypes = ['product']; // ← ADD YOUR CPTs HERE
const defaultLang = languages.find(l => l.default)?.slug || 'en';
const targetLangs = languages.map(l => l.slug);

const jobs = [];
for (const pt of postTypes) {
  for (const lang of targetLangs) {
    jobs.push({
      post_type: pt,
      target_lang: lang,
      default_lang: defaultLang,
      wp_base_url: config.wp_base_url,
      deepseek_api_url: config.deepseek_api_url,
      deepseek_model: config.deepseek_model,
      posts_per_batch: config.posts_per_batch || 50,
    });
  }
}

return jobs.map(j => ({ json: j }));

// ── Fetch ALL untranslated posts across ALL pages for ALL jobs ──
// Replaces the old single-page "GET Untranslated Posts" + "Flatten Post List" nodes.
// Uses $helpers.httpRequestWithAuthentication to reuse the stored Basic Auth credential.

const jobs = $input.all().map(i => i.json);
const allPostItems = [];

for (const job of jobs) {
  let page = 1;
  let hasMore = true;
  const perPage = job.posts_per_batch || 50;

  while (hasMore) {
    const response = await $helpers.httpRequestWithAuthentication.call(
      $nodeItem,
      'httpBasicAuth',
      {
        method: 'GET',
        url: `${job.wp_base_url}/untranslated-posts`,
        qs: {
          post_type:   job.post_type,
          target_lang: job.target_lang,
          per_page:    perPage,
          page:        page
        }
      }
    );

    const posts = response.posts || [];

    if (posts.length === 0) {
      hasMore = false;
      break;
    }

    for (const post of posts) {
      for (const lang of post.missing_langs) {
        allPostItems.push({
          json: {
            post_id:          post.id,
            post_type:        post.post_type,
            source_lang:      post.source_lang,
            target_lang:      lang,
            wp_base_url:      job.wp_base_url,
            deepseek_api_url: job.deepseek_api_url,
            deepseek_model:   job.deepseek_model
          }
        });
      }
    }

    // If we got fewer results than a full page → we are on the last page
    hasMore = posts.length >= perPage;
    page++;

    console.log(`[${job.post_type} → ${job.target_lang}] page ${page - 1}: fetched ${posts.length} posts (total so far: ${allPostItems.length})`);
  }
}

if (allPostItems.length === 0) {
  // Return a single sentinel so the workflow doesn't crash on empty input
  return [{ json: { __skip: true, reason: 'No untranslated posts found' } }];
}

return allPostItems;

const responses = $input.all();
const jobs = $('Fetch ALL Untranslated Posts (Paginated)').all();

return responses.map((inputItem, index) => {
  const payload = inputItem.json;
  const job = jobs[index].json;

  const bundle = {
    title:   payload.translatable.title,
    content: payload.translatable.content,
    excerpt: payload.translatable.excerpt,
    slug:    payload.translatable.slug,
  };

  const meta_to_translate = {};
  for (const [key, info] of Object.entries(payload.meta || {})) {
    if (info.translatable) {
      const val = (info.type === 'json' || info.type === 'serialized')
        ? JSON.stringify(info.raw_value)
        : String(info.raw_value);
      if (val && val.trim()) meta_to_translate[key] = val;
    }
  }

  const acf_to_translate = {};
  for (const [key, info] of Object.entries(payload.acf_fields || {})) {
    if (info.translatable && info.value) {
      acf_to_translate[key] = String(info.value);
    }
  }

  const taxonomy_source_terms = {};
  for (const [tax, terms] of Object.entries(payload.taxonomies || {})) {
    taxonomy_source_terms[tax] = terms.map(t => ({
      source_term_id: t.term_id,
      translations: t.translations
    }));
  }

  const has_blocks = payload.has_blocks === true;
  const block_segments = [];

  if (has_blocks && payload.blocks?.segments?.length > 0) {
    for (const seg of payload.blocks.segments) {
      if (seg.text && seg.text.trim()) {
        block_segments.push({
          index:    seg.index,
          sub_path: seg.sub_path,
          is_html:  seg.is_html,
          original: seg.text,
        });
      }
    }
  }

  return {
    json: {
      ...job,
      post_payload: payload,
      bundle,
      meta_to_translate,
      acf_to_translate,
      taxonomy_source_terms,
      has_blocks,
      block_segments,
      block_original_content: has_blocks ? (payload.blocks?.original_content ?? null) : null,
      target_lang: job.target_lang,
      source_lang: payload.source_lang,
    }
  };
});

function decodeUnicodeEscapes(str) {
  if (typeof str !== 'string') return str;
  return str.replace(/\\u([0-9a-fA-F]{4})/g, (_, hex) =>
    String.fromCharCode(parseInt(hex, 16))
  );
}

function sanitizeForJSON(str) {
  if (typeof str !== 'string') return str;
  return str
    .replace(/<!--\s*wp:[^>]*\{[^}]+\}[^>]*-->/g, (match) =>
      match.replace(/"/g, '\\"')
    )
    .replace(/\r?\n/g, "\\n");
}

const CHUNK_SIZE = 12;
const FIELD_LIMIT = 3000;

return $input.all().flatMap(inputItem => {
  const item = inputItem.json;
  const target_lang = item.target_lang;
  const source_lang = item.source_lang;

  const system_prompt = `You are a professional multilingual content translator for WordPress.

STRICT RULES (MUST FOLLOW):
1. Return ONLY valid JSON that passes JSON.parse().
2. Do NOT include markdown, explanations, or extra text.
3. Escape ALL double quotes inside strings using \\".
4. Preserve ALL HTML tags exactly.
5. Translate ONLY human-readable text.

TRANSLATION REQUIREMENTS:
- You MUST translate ALL fields inside:
  core.title
  core.excerpt
  core.content (if exists)
  meta (all values)
  acf (all values)
  blocks[].original → blocks[].translated

- DO NOT leave ANY field untranslated.
- DO NOT return original text.

OUTPUT STRUCTURE (MUST MATCH EXACTLY):

{
  "core": {
    "title": "...translated...",
    "excerpt": "...translated...",
    "slug": "...translated-slug...",
    "content": "...translated..." // only if provided
  },
  "meta": {},
  "acf": {},
  "blocks": [
    {
      "index": number,
      "sub_path": string,
      "translated": string
    }
  ]
}

SLUG RULE:
- lowercase
- hyphen-separated
- no spaces
- no special characters`;

  const requests = [];

  const core_bundle = {
    title:   sanitizeForJSON(item.bundle.title),
    excerpt: sanitizeForJSON(item.bundle.excerpt),
    slug:    item.bundle.slug,
    ...(!item.has_blocks && item.bundle.content
      ? { content: sanitizeForJSON(item.bundle.content) }
      : {}),
  };

  const meta_entries = Object.entries(item.meta_to_translate || {});
  const acf_entries  = Object.entries(item.acf_to_translate  || {});
  const meta_size    = JSON.stringify(item.meta_to_translate || {}).length;
  const acf_size     = JSON.stringify(item.acf_to_translate  || {}).length;

  if (meta_size + acf_size < FIELD_LIMIT) {
    requests.push({
      chunk_type: 'core',
      payload: {
        core: core_bundle,
        meta: item.meta_to_translate || {},
        acf:  item.acf_to_translate  || {}
      }
    });
  } else {
    requests.push({
      chunk_type: 'core',
      payload: { core: core_bundle }
    });

    const META_CHUNK = 5;

    for (let i = 0; i < meta_entries.length; i += META_CHUNK) {
      requests.push({
        chunk_type: 'meta',
        payload: { meta: Object.fromEntries(meta_entries.slice(i, i + META_CHUNK)) }
      });
    }

    for (let i = 0; i < acf_entries.length; i += META_CHUNK) {
      requests.push({
        chunk_type: 'acf',
        payload: { acf: Object.fromEntries(acf_entries.slice(i, i + META_CHUNK)) }
      });
    }
  }

  const blocks_for_ds = (item.block_segments || []).map(seg => ({
    index:    seg.index,
    sub_path: seg.sub_path,
    original: sanitizeForJSON(decodeUnicodeEscapes(seg.original)),
  }));

  for (let i = 0; i < blocks_for_ds.length; i += CHUNK_SIZE) {
    requests.push({
      chunk_type: 'blocks',
      payload: { blocks: blocks_for_ds.slice(i, i + CHUNK_SIZE) }
    });
  }

  const total_chunks = requests.length;
  const post_id      = item.post_payload.id;

  const shared_context = {
    post_id,
    target_lang,
    source_lang,
    chunk_type: null,
    chunk_index: null,
    total_chunks,
    wp_base_url:            item.wp_base_url,
    deepseek_model:         item.deepseek_model,
    deepseek_api_url:       item.deepseek_api_url,
    has_blocks:             item.has_blocks,
    bundle:                 item.bundle,
    block_segments:         item.block_segments,
    block_original_content: item.block_original_content,
    taxonomy_source_terms:  item.taxonomy_source_terms,
    post_payload_id:        post_id,
  };

  return requests.map((req, i) => ({
    json: {
      ...shared_context,
      chunk_type:  req.chunk_type,
      chunk_index: i,
      deepseek_request: {
        model:       item.deepseek_model,
        max_tokens:  4096,
        temperature: 0.2,
        messages: [
          { role: 'system', content: system_prompt },
          {
            role: 'user',
            content:
`Translate from ${source_lang} to ${target_lang}.

You MUST translate ALL fields including:
- core.title
- core.excerpt
- core.content (if exists)
- meta (all values)
- acf (all values)
- blocks[].original → blocks[].translated

Do NOT leave any field untranslated.
Do NOT return original text.

Return ONLY valid JSON.

INPUT:
${JSON.stringify(req.payload)}`
          }
        ]
      }
    }
  }));
});

// Re-attach context from Prepare node by index
const dsResponses = $input.all();
const reqItems    = $('Prepare DeepSeek Request').all();

return dsResponses.map((inputItem, index) => {
  const ds_resp = inputItem.json;
  const req     = reqItems[index].json;

  return {
    json: {
      choices: ds_resp.choices,
      post_id:                req.post_id,
      chunk_index:            req.chunk_index,
      chunk_type:             req.chunk_type,
      total_chunks:           req.total_chunks,
      target_lang:            req.target_lang,
      source_lang:            req.source_lang,
      wp_base_url:            req.wp_base_url,
      deepseek_model:         req.deepseek_model,
      deepseek_api_url:       req.deepseek_api_url,
      has_blocks:             req.has_blocks,
      bundle:                 req.bundle,
      block_segments:         req.block_segments,
      block_original_content: req.block_original_content,
      taxonomy_source_terms:  req.taxonomy_source_terms,
    }
  };
});

function decodeUnicodeEscapes(str) {
  if (typeof str !== 'string') return str;
  return str.replace(/\\u([0-9a-fA-F]{4})/g, (_, hex) =>
    String.fromCharCode(parseInt(hex, 16))
  );
}

const parsedChunks = [];

for (const inputItem of $input.all()) {
  const item          = inputItem.json;
  const deepseek_resp = item;

  if (!deepseek_resp.choices || deepseek_resp.choices.length === 0) {
    throw new Error(`DeepSeek returned no choices for post ${item.post_id} chunk ${item.chunk_index}`);
  }

  let raw = deepseek_resp.choices[0].message.content.trim();
  raw = raw.replace(/^```json\s*/i, '').replace(/\s*```$/i, '');

  let translated;
  try {
    translated = JSON.parse(raw);
  } catch(e) {
    throw new Error(`Failed to parse DeepSeek JSON for post ${item.post_id} chunk ${item.chunk_index}: ${e.message}`);
  }

  parsedChunks.push({ item, translated });
}

// Group by post_id + target_lang
const groups = {};
for (const { item, translated } of parsedChunks) {
  const key = `${item.post_id}_${item.target_lang}`;
  if (!groups[key]) {
    groups[key] = { item, core_chunk: null, merged_meta: {}, merged_acf: {}, block_chunks: [] };
  }
  const g = groups[key];

  if (item.chunk_type === 'core') {
    g.core_chunk = translated;
    if (translated.meta) Object.assign(g.merged_meta, translated.meta);
    if (translated.acf)  Object.assign(g.merged_acf,  translated.acf);
  } else if (item.chunk_type === 'meta') {
    Object.assign(g.merged_meta, translated.meta || {});
  } else if (item.chunk_type === 'acf') {
    Object.assign(g.merged_acf, translated.acf || {});
  } else if (item.chunk_type === 'blocks') {
    g.block_chunks.push({ chunk_index: item.chunk_index, translated });
  }
}

const results = [];

for (const { item, core_chunk, merged_meta, merged_acf, block_chunks } of Object.values(groups)) {
  if (!core_chunk?.core?.title) {
    throw new Error(
      `Missing title translation.\nPost: ${item.post_id}\nChunk: core\nRaw: ${JSON.stringify(core_chunk)}`
    );
  }
  block_chunks.sort((a, b) => a.chunk_index - b.chunk_index);

  const all_translated_blocks = [];
  for (const { translated } of block_chunks) {
    if (translated.blocks) all_translated_blocks.push(...translated.blocks);
  }

  const tax_map = {};
  for (const [tax, source_terms] of Object.entries(item.taxonomy_source_terms || {})) {
    const target_ids = [];
    for (const t of source_terms) {
      const tid = t.translations?.[item.target_lang];
      if (tid) target_ids.push(tid);
    }
    if (target_ids.length > 0) tax_map[tax] = target_ids;
  }

  let final_content = null;
  if (item.has_blocks && item.block_original_content && all_translated_blocks.length > 0) {
    let content = item.block_original_content;

    for (const tb of all_translated_blocks) {
      const orig_seg = (item.block_segments || []).find(s => s.index === tb.index);
      if (!orig_seg || !tb.translated) continue;

      const original_text   = decodeUnicodeEscapes(orig_seg.original);
      const translated_text = decodeUnicodeEscapes(tb.translated);

      if (!original_text || !translated_text) continue;
      if (original_text === translated_text) continue;

      content = content.split(orig_seg.original).join(translated_text);
      if (orig_seg.original !== original_text) {
        content = content.split(original_text).join(translated_text);
      }
    }
    final_content = content;
  }

  results.push({
    json: {
      wp_base_url: item.wp_base_url,
      save_payload: {
        source_id:   item.post_id,
        target_lang: item.target_lang,
        translated: {
          title:   core_chunk?.core?.title   ?? "__MISSING_TRANSLATION__",
          content: item.has_blocks ? null    : (core_chunk?.core?.content || item.bundle.content),
          excerpt: core_chunk?.core?.excerpt || item.bundle.excerpt,
          slug:    core_chunk?.core?.slug    || (item.bundle.slug + '-' + item.target_lang),
        },
        meta:          merged_meta,
        acf:           merged_acf,
        tax_map,
        block_content: final_content,
      }
    }
  });
}

return results;

const responses = $input.all();
for (const resp of responses) {
  const result = resp.json;
  console.log(`✅ POST saved: ID=${result.post_id}, lang=${result.target_lang}, action=${result.action}`);
}
return responses;
